SELECT tl.id AS id, tl.task_id AS taskId, tl.task_name AS taskName, tl.task_params AS taskParams, tl.process_status AS processStatus, tl.process_duration AS processDuration, tl.process_log AS processLog, tl.ip_address AS ipAddress, tl.update_time AS updateTime, tl.create_time AS createTime FROM t_quartz_task_log tl
AND tl.task_id = #{queryDTO.taskId}
ORDER BY tl.create_time DESC
